fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since the array has at least one element, we only need to check pairs of consecutive elements.
    // If for every i, arr[i] <= arr[i+1], then the entire array is nondecreasing.
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}